"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type FanShuffleCard = {
  id: string;
  title: string;
  subtitle?: string;
};

export type FanShuffleProps = {
  cards: FanShuffleCard[];
  className?: string;
  onOrderChange?: (ids: string[]) => void;
};

/**
 * Fan of cards you can drag left/right to shuffle the stack order.
 */
function FanShuffle({ cards, className, onOrderChange }: FanShuffleProps) {
  const [order, setOrder] = React.useState(cards.map((c) => c.id));
  const dragRef = React.useRef<{ id: string; x: number } | null>(null);
  const [dx, setDx] = React.useState(0);

  React.useEffect(() => {
    setOrder(cards.map((c) => c.id));
  }, [cards]);

  const byId = React.useMemo(
    () => Object.fromEntries(cards.map((c) => [c.id, c])),
    [cards],
  );

  const onPointerDown = (id: string, e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    dragRef.current = { id, x: e.clientX };
    setDx(0);
  };

  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current) return;
    setDx(e.clientX - dragRef.current.x);
  };

  const onPointerUp = () => {
    if (!dragRef.current) return;
    if (Math.abs(dx) > 48) {
      const next = [...order];
      if (dx > 0) next.push(next.shift()!);
      else next.unshift(next.pop()!);
      setOrder(next);
      onOrderChange?.(next);
    }
    dragRef.current = null;
    setDx(0);
  };

  return (
    <div
      className={cn(
        "relative mx-auto h-[200px] w-full max-w-md touch-none select-none",
        className,
      )}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
    >
      {order.map((id, i) => {
        const card = byId[id];
        if (!card) return null;
        const mid = (order.length - 1) / 2;
        const offset = i - mid;
        const isTop = i === 0;
        return (
          <div
            key={id}
            onPointerDown={(e) => onPointerDown(id, e)}
            className={cn(
              "absolute left-1/2 top-6 w-[68%] -translate-x-1/2 cursor-grab rounded-2xl border border-border bg-card p-4 shadow-[var(--shadow-lift)] active:cursor-grabbing",
              !isTop && "pointer-events-none",
            )}
            style={{
              zIndex: order.length - i,
              transform: `translate(calc(-50% + ${offset * 18 + (isTop ? dx * 0.35 : 0)}px), ${i * 10}px) rotate(${offset * 4 + (isTop ? dx * 0.04 : 0)}deg)`,
              opacity: 1 - i * 0.12,
            }}
          >
            <div className="text-sm font-semibold">{card.title}</div>
            {card.subtitle ? (
              <div className="mt-1 text-xs text-muted-foreground">
                {card.subtitle}
              </div>
            ) : null}
          </div>
        );
      })}
      <p className="absolute bottom-2 left-0 right-0 text-center text-[11px] text-muted-foreground">
        Drag to shuffle
      </p>
    </div>
  );
}

export { FanShuffle };
